import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:go_router/go_router.dart';
import 'package:refract/core/integration_models.dart';
import 'package:refract/core/models.dart';
import 'package:refract/core/repository.dart';
import 'package:refract/features/integrations/integrations_page.dart';
import 'package:refract/features/integrations/email_copy_page.dart';
import 'package:refract/features/integrations/email_copies_page.dart';
import 'package:refract/features/integrations/calendar_export_page.dart';
IntegrationCapability capability(String id,{bool enabled=false,bool research=false})=>IntegrationCapability.fromJson({'id':id,'name':id=='selected_email'?'Selected email copy':id=='gmail'?'Google mailbox adapter':'Reviewed calendar file','availability':research?'research_only':'available_local','scope':'Explicit local selection only.','limitations':'No account connection.','categories':research?<String>[]:id=='selected_email'?['receipt']:['confirmed_dates'],'policy':{'connector_id':id,'enabled':enabled,'categories':enabled?[id=='selected_email'?'receipt':'confirmed_dates']:<String>[],'revision':1}});
class _FakeRepository implements RefractRepository{
 final calls=<String>[];Map<String,dynamic>? lastPayload;
 @override dynamic integrations(String action,[dynamic payload]){calls.add(action);if(payload is Map<String,dynamic>){lastPayload=payload;}switch(action){case 'email_delete':return {'library_removed':true,'input_blob_removed':true,'warning':'Removed from active library, not secure erasure.'};case 'email_preview':return {'copy_text':'Exactly reviewed body only','review_hash':'email-review','statement':'Unverified selected copy'};case 'email_import':return {'id':'selected-copy'};case 'calendar_preview':return {'ics':'BEGIN:VCALENDAR\r\nEND:VCALENDAR\r\n','review_hash':'calendar-review','prepared_ts':100,'statement':'Date only, no appointment or delivery claim'};case 'calendar_export':return {'ics':'BEGIN:VCALENDAR\r\nEND:VCALENDAR\r\n','review_hash':'calendar-review','prepared_ts':100,'statement':'No external import confirmation'};default:return true;}}
 @override dynamic noSuchMethod(Invocation invocation)=>super.noSuchMethod(invocation);
}
Future<void> reveal(WidgetTester tester,Finder finder,{double delta=160})async{await tester.scrollUntilVisible(finder,delta,scrollable:find.byType(Scrollable).first);await tester.pumpAndSettle();}
void main(){
 test('Availability is not connection status and selected email source stays distinct',(){expect(capability('gmail',enabled:true,research:true).available,false);expect(capability('selected_email').enabled,false);expect(sourceTypeFromString('email_copy'),SourceType.emailCopy);expect(sourceTypeLabel(SourceType.emailCopy),'Selected email copy');});
 testWidgets('Research capabilities cannot be enabled and local consent is explicit',(tester)async{final fake=_FakeRepository();await tester.pumpWidget(ProviderScope(overrides:[bootstrapProvider.overrideWith((ref)async=>fake),integrationCatalogProvider.overrideWith((ref)async=>[capability('gmail',research:true),capability('selected_email')])],child:const MaterialApp(home:IntegrationsPage())));await tester.pumpAndSettle();expect(find.text('Research only — no connection'),findsOneWidget);expect(find.byType(SwitchListTile),findsOneWidget);expect(fake.calls,isEmpty);await reveal(tester,find.text('Apply local consent'));await tester.tap(find.text('Apply local consent'));await tester.pumpAndSettle();expect(fake.calls,isEmpty);await tester.tap(find.text('Cancel'));await tester.pumpAndSettle();expect(fake.calls,isEmpty);expect(find.text('Review a selected email copy'),findsNothing);});
 testWidgets('Email copy requires preview and explicit confirmation; excluded headers default off',(tester)async{final fake=_FakeRepository();final router=GoRouter(routes:[GoRoute(path:'/',builder:(_,s)=>const EmailCopyPage()),GoRoute(path:'/reader/:id',builder:(_,s)=>Scaffold(body:Text('Private copy ${s.pathParameters['id']}')))]);addTearDown(router.dispose);await tester.pumpWidget(ProviderScope(overrides:[bootstrapProvider.overrideWith((ref)async=>fake),integrationCatalogProvider.overrideWith((ref)async=>[capability('selected_email',enabled:true)])],child:MaterialApp.router(routerConfig:router)));await tester.pumpAndSettle();expect(find.text('Save reviewed copy to private library'),findsNothing);await tester.enterText(find.widgetWithText(TextField,'Selected raw plain-text email'),'Content-Type: text/plain\r\n\r\nReviewed body');tester.testTextInput.hide();await tester.pumpAndSettle();await tester.tap(find.byType(DropdownButtonFormField<String>));await tester.pumpAndSettle();await tester.tap(find.text('receipt').last);await tester.pumpAndSettle();await reveal(tester,find.text('Build exact email-copy preview'));await tester.tap(find.text('Build exact email-copy preview'));await tester.pumpAndSettle();expect(fake.calls,['email_preview']);expect(fake.lastPayload?['include_subject'],false);expect(fake.lastPayload?['include_sender'],false);expect(fake.lastPayload?['include_declared_date'],false);await reveal(tester,find.text('Save reviewed copy to private library'));await tester.tap(find.text('Save reviewed copy to private library'));await tester.pumpAndSettle();expect(fake.calls,['email_preview']);await tester.tap(find.text('Cancel'));await tester.pumpAndSettle();await tester.tap(find.text('Save reviewed copy to private library'));await tester.pumpAndSettle();await tester.tap(find.text('Confirm'));await tester.pumpAndSettle();expect(fake.lastPayload?['review_hash'],'email-review');expect(find.text('Private copy selected-copy'),findsOneWidget);});
 testWidgets('Calendar exports generic reviewed titles, not private source titles; changes clear preview',(tester)async{final fake=_FakeRepository();final candidates=IntegrationCalendarCandidates.fromJson({'events':[{'id':'event','source_id':'source','block_idx':0,'local_title':'PRIVATE SOURCE','date':'2027-01-02','evidence':'Exact date evidence','source_current':true}],'limited':false});await tester.pumpWidget(ProviderScope(overrides:[bootstrapProvider.overrideWith((ref)async=>fake),integrationCalendarProvider.overrideWith((ref)async=>candidates)],child:const MaterialApp(home:CalendarExportPage())));await tester.pumpAndSettle();expect(find.text('Save reviewed calendar file'),findsNothing);await tester.tap(find.byType(CheckboxListTile).first);await tester.pumpAndSettle();await reveal(tester,find.text('Build exact calendar-file preview'));await tester.tap(find.text('Build exact calendar-file preview'));await tester.pumpAndSettle();expect(fake.calls,['calendar_preview']);expect(fake.lastPayload?['include_evidence'],false);expect((fake.lastPayload?['events'] as List).single['title'],'Reviewed date');await reveal(tester,find.text('Save reviewed calendar file'));await tester.tap(find.text('Save reviewed calendar file'));await tester.pumpAndSettle();expect(fake.calls,['calendar_preview']);await tester.tap(find.text('Cancel'));await tester.pumpAndSettle();await reveal(tester,find.widgetWithText(TextField,'Explicit export title'),delta:-160);await tester.enterText(find.widgetWithText(TextField,'Explicit export title'),'A deliberately chosen title');await tester.pumpAndSettle();expect(find.text('Save reviewed calendar file'),findsNothing);});
 testWidgets('Retained-copy deletion does not enable capture and requires confirmation',(tester)async{final fake=_FakeRepository();await tester.pumpWidget(ProviderScope(overrides:[bootstrapProvider.overrideWith((ref)async=>fake),integrationCopiesProvider.overrideWith((ref)async=>[{'id':'copy-id','title':'Selected email copy','captured_ts':100}])],child:const MaterialApp(home:EmailCopiesPage())));await tester.pumpAndSettle();await reveal(tester,find.text('Delete retained email copy'));await tester.tap(find.text('Delete retained email copy'));await tester.pumpAndSettle();expect(fake.calls,isEmpty);await tester.tap(find.text('Cancel'));await tester.pumpAndSettle();await tester.tap(find.text('Delete retained email copy'));await tester.pumpAndSettle();await tester.tap(find.text('Confirm'));await tester.pumpAndSettle();expect(fake.calls,['email_delete']);expect(find.text('Removed from active library, not secure erasure.'),findsOneWidget);});

 testWidgets('Changing allowed categories clears stale email selection without a dropdown assertion',(tester)async{final state=StateProvider<IntegrationCapability>((ref)=>capability('selected_email',enabled:true));await tester.pumpWidget(ProviderScope(overrides:[integrationCatalogProvider.overrideWith((ref)async=>[ref.watch(state)])],child:const MaterialApp(home:EmailCopyPage())));await tester.pumpAndSettle();await tester.tap(find.byType(DropdownButtonFormField<String>));await tester.pumpAndSettle();await tester.tap(find.text('receipt').last);await tester.pumpAndSettle();final container=ProviderScope.containerOf(tester.element(find.byType(EmailCopyPage)));container.read(state.notifier).state=IntegrationCapability(id:'selected_email',name:'Selected email copy',availability:'available_local',scope:'Local',limitations:'No account',categories:['travel'],enabled:true,allowedCategories:['travel'],revision:2);await tester.pumpAndSettle();expect(tester.takeException(),isNull);expect(tester.widget<DropdownButtonFormField<String>>(find.byType(DropdownButtonFormField<String>)).initialValue,isNull);expect(find.text('Save reviewed copy to private library'),findsNothing);});

}
